const G='46552447679363c70f7ef8.58193285';
const PAT=/^(pt|no|nb|nn)([-_]|$)/i;
const NAME=/portug|norw|bokm|nynorsk/i;
const pr=$('Fetch Projects').first().json;
const projects=(pr.body&&pr.body.projects)||[];
const pname={};
for (const p of projects) pname[p.project_id]=p.name;
const hdr=pr.headers||{};
