for (const it of $input.all()) {
  const j=it.json; const sc=j.statusCode; const body=j.body||{};
  if (sc&&sc>=300) { errors.push({sc:sc,b:JSON.stringify(body).slice(0,200)}); continue; }
  if (body.languages) {
    const pid=body.project_id; seenProj[pid]=1;
    const hits=[];
    for (const l of body.languages) {
      if (PAT.test(l.lang_iso||'')||NAME.test(l.lang_name||'')||[708,759,760,1057].indexOf(l.lang_id)>=0) hits.push({id:l.lang_id,iso:l.lang_iso,name:l.lang_name,plural:l.plural_forms});
    }
    projRows.push({pid:pid,name:pname[pid]||pid,nlangs:body.languages.length,hits:hits});
    if (pid===G) glossLangs=body.languages.map(function(l){return l.lang_id+'|'+l.lang_iso+'|'+l.lang_name;});
  }
  if (body.data) {
    gl.pages++;
    for (const t of body.data) {
      gl.terms++;
      let t759=null,t760=null; let has708=false,has759=false,has760=false;
      for (const x of (t.translations||[])) {
        const txt=(typeof x.translation==='string')?x.translation.trim():'';
        if (PAT.test(x.langIso||'')||NAME.test(x.langName||'')||[708,759,760,1057].indexOf(x.langId)>=0) {
          const k=x.langId+'|'+x.langIso+'|'+x.langName;
          if(!gl.combos[k]) gl.combos[k]={rows:0,nonEmpty:0};
          gl.combos[k].rows++; if(txt) gl.combos[k].nonEmpty++;
        }
        if(x.langId===708)has708=true; if(x.langId===759)has759=true; if(x.langId===760)has760=true; if (x.langId===759) t759=txt; if (x.langId===760) t760=txt;
        gl.unmapped[x.langId+'|'+x.langIso+'|'+x.langName]=(gl.unmapped[x.langId+'|'+x.langIso+'|'+x.langName]||0)+1;
      }
      if(has759) gl.nbTerms.push({term:t.term,created:t.createdAt,updated:t.updatedAt,has760:has760}); if(!has708) gl.no708.push({term:t.term,created:t.createdAt}); if(!has760&&!has759) gl.noNorw.push(t.term);
      if (t759&&!t760) gl.only759.push({term:t.term,nb:t759});
      if (t760&&!t759) gl.only760count++;
      if (t759&&t760) { gl.both++; if (t759!==t760) gl.bothDiffer.push({term:t.term,nb:t759,no:t760}); else gl.bothSame++; }
    }
  }
}
const missing=projects.filter(function(p){return !seenProj[p.project_id];}).map(function(p){return p.name;});
return [{json:{projects_header_total:hdr['x-pagination-total-count'],projects_returned:projects.length,languages_missing_for:missing,errors:errors,projRows:projRows,glossLangs:glossLangs,glossary:gl}}];
